});

test('issueInvoice uses existing numbers to determine next number', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const existing = ['INV-2025-0001', 'INV-2025-0002', 'INV-2025-0003'];
  const issueResult = issueInvoice(result.value, existing);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2025-0004');
});

test('issueInvoice does not mutate the original invoice', () => {
