test('lineDiscount calculates discount amount correctly', () => {
  // 10% of €95.00 = €9.50
  assert.equal(lineDiscount({ qty: 1, unitPrice: 9500, discountPercent: 10 }), 950);
  // 50% of €120.00 = €60.00
  assert.equal(lineDiscount({ qty: 1, unitPrice: 120000, discountPercent: 50 }), 60000);
